package notebook

import (
	"bytes"
	"database/sql"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
	"time"
	"unicode/utf8"
)

// collectedAttempts is the number of collected live-heap samples per payload
// size: one cold read to warm allocator and page caches, then two warmed
// samples whose steadier reading feeds the growth comparison.
// collectedGrowthBudget bounds both the cross-size growth comparison and the
// per-size post-GC baseline shift: one yardstick for transient growth and
// retained heap alike.
const (
	collectedAttempts     = 3
	collectedGrowthBudget = 1 << 20
)

func TestMarkdownRetainedMemory(t *testing.T) {
	for _, kind := range []string{"database_title", "row_text", "block_code", "block_rich_text", "option_name", "option_schema"} {
		t.Run(kind, func(t *testing.T) {
			sizes := []int{1 << 20}
			large := os.Getenv("NOTEBOOK_LARGE_MEMORY_TESTS") == "1"
			if kind == "option_schema" || large {
				sizes = readerMemorySizes()
			}
			if kind == "option_schema" && !large {
				// At 16 MiB, retaining every option id exceeds the growth allowance.
				sizes = append(sizes, 16<<20)
			}
			// Whole-read heap samples and the growth comparison must stay sequential.
			schemaPeaks := map[int]uint64{}
			type memoryCase struct {
				size      int
				collected bool
			}
			cases := make([]memoryCase, 0, len(sizes)+2)
			for _, size := range sizes {
				cases = append(cases, memoryCase{size: size})
			}
			if kind == "option_schema" && !large {
				cases = append(cases, memoryCase{size: 1 << 20, collected: true}, memoryCase{size: 16 << 20, collected: true})
			}
			for _, test := range cases {
				size := test.size
				name := fmt.Sprintf("%gMiB", float64(size)/(1<<20))
				if test.collected {
					name += "_live"
				}
				t.Run(name, func(t *testing.T) {
					started := time.Now()
					f, created := readerQueryFixture(t)
					database := created.Refs["db"].Ref
					wantRefs := map[ID]Ref{f.page.ID: f.page}
					addRefs := func(result WriteResult) {
						for _, assigned := range result.Refs {
							wantRefs[assigned.Ref.ID] = assigned.Ref
						}
					}
					addRefs(created)
					limit := 1
					optionCount := 0
					payload := kind != "database_title" && kind != "option_schema"
					var fragments []string
					id, path := created.Refs["db"].Ref.ID, "$.title"
					switch kind {
					case "row_text":
						added := liveReadUpdate(t, f, "text-property", CreatePropertyOp{CreateFields: CreateFields{Ref: "text"}, Database: Target{Ref: &database}, Definition: PropertyDef{Name: "Note", Type: TextType}})
						addRefs(added)
						cell, err := EncodeCellValue(CellValue{Type: TextType, Value: "seed"})
						if err != nil {
							t.Fatal(err)
						}
						if err := f.in.db.transaction(t.Context(), func(tx *sql.Tx) error {
							_, err := tx.ExecContext(t.Context(), `INSERT INTO cells(row_id,property_id,value) VALUES(?,?,json_set(?,'$.value',?))`, created.Refs["big"].Ref.ID, added.Refs["text"].Ref.ID, string(cell), "payloadstart"+strings.Repeat("x", size)+"payloadend")
							return err
						}); err != nil {
							t.Fatal(err)
						}
					case "block_code", "block_rich_text":
						content := Content{Kind: Code, Code: "seed", Language: "go"}
						path = "$.content.text"
						if kind == "block_rich_text" {
							content = Content{Kind: Paragraph, Text: RichText{{Text: "seed", Marks: []Mark{Bold}}}}
							path = "$.content.text[0].text"
						}
						added := liveReadUpdate(t, f, "retained-block", CreateBlockOp{CreateFields: CreateFields{Ref: "block"}, Place: Placement{Page: Target{Ref: &f.page}}, Content: content})
						addRefs(added)
						id = added.Refs["block"].Ref.ID
					case "option_name":
						first := created.Refs["first"].Ref
						row, property := created.Refs["big"].Ref, created.Refs["tags"].Ref
						liveReadUpdate(t, f, "selected-option", SetCellOp{Row: Target{Ref: &row}, Cell: CellInput{Property: Target{Ref: &property}, Value: CellInputValue{Options: []Target{{Ref: &first}}}}})
						id, path = first.ID, "$.name"
					case "option_schema":
						// Populate every ordered id; absent option ids do not exercise schema retention.
						property := created.Refs["tags"].Ref
						name := func(n int) string { return fmt.Sprintf("choice%06d", n) + strings.Repeat("x", 144) }
						data, err := json.Marshal(Option{Property: property.ID, Name: name(0), Color: Gray})
						if err != nil {
							t.Fatal(err)
						}
						optionBytes := len(data) + len(spillID(OptionKind, 100)) + 3
						count := (size + optionBytes - 1) / optionBytes
						optionCount = count
						order := make([]ID, 0, count+2)
						order = append(order, created.Refs["first"].Ref.ID)
						for n := count - 1; n >= 0; n-- {
							id := spillID(OptionKind, uint64(n+100))
							order = append(order, id)
						}
						optionName := func(i int) string { return name(count - 1 - i) }
						// Keep the default small fixtures in-process; amortize the helper build on large schemas.
						external := size >= 8<<20
						if external {
							if err := spillExternalOptions(t, f.in, property.ID, order[1:], optionName); err != nil {
								t.Fatal(err)
							}
						}
						if err := f.in.db.transaction(t.Context(), func(tx *sql.Tx) error {
							if !external {
								if err := spillOptions(t, tx, property.ID, order[1:], optionName); err != nil {
									return err
								}
							}
							order = append(order, created.Refs["second"].Ref.ID)
							if err := putOrder(t.Context(), tx, property.ID, OptionOrderGroup, order); err != nil {
								return err
							}
							selected := []ID{order[count], order[count/2], order[1]}
							order = nil
							cell, err := EncodeCellValue(CellValue{Type: MultiSelectType, Value: selected})
							if err != nil {
								return err
							}
							_, err = tx.ExecContext(t.Context(), `INSERT INTO cells(row_id,property_id,value) VALUES(?,?,?)`, created.Refs["big"].Ref.ID, property.ID, string(cell))
							return err
						}); err != nil {
							t.Fatal(err)
						}
						fragments = append(fragments, name(count-1)+", "+name(count-count/2)+", "+name(0))
						// Batch schema-only continuations rather than issue one request per option.
						limit = 500
					}
					if kind != "row_text" && kind != "option_schema" {
						if err := f.in.db.transaction(t.Context(), func(tx *sql.Tx) error {
							_, err := tx.ExecContext(t.Context(), `UPDATE items SET data=json_set(data,?,?) WHERE id=?`, path, "payloadstart"+strings.Repeat("x", size)+"payloadend", id)
							if err == nil && kind == "option_name" {
								_, err = tx.ExecContext(t.Context(), `UPDATE options SET name_key=(SELECT json_extract(data,'$.name') FROM items WHERE id=?) WHERE id=?`, id, id)
							}
							return err
						}); err != nil {
							t.Fatal(err)
						}
					}
					raw, err := json.Marshal(map[string]any{"page": f.page.ID, "format": "markdown", "limit": limit})
					if err != nil {
						t.Fatal(err)
					}
					fixtureElapsed := time.Since(started)
					readStart := time.Now()
					var body []byte
					if test.collected {
						// Keep the selected measured response outside the Go
						// heap until all three reads have contributed to retention.
						responsePath := filepath.Join(t.TempDir(), "response.json")
						peak, firstBaseline := measureMarkdownLiveReads(t, f.in, raw, responsePath)
						lastBaseline := settledReaderHeap()
						shift := collectedRetentionShift(firstBaseline, lastBaseline)
						t.Logf("retained=%d collected live-heap baseline shift=%d first=%d last=%d", size, shift, firstBaseline, lastBaseline)
						if shift > collectedGrowthBudget {
							t.Errorf("Markdown read retained %s for %d MiB payload: post-GC live heap rose %d bytes across %d collected reads, exceeds 1 MiB", kind, size>>20, shift, collectedAttempts)
						}
						body, err = os.ReadFile(responsePath)
						schemaPeaks[size] = peak
						t.Logf("retained=%d sampled collected live-heap growth=%d response=%d fixture=%s read=%s", size, peak, len(body), fixtureElapsed, time.Since(readStart))
					} else {
						var peak, retained uint64
						body, peak, retained, err = measureReaderHeap(t, f.in, raw)
						t.Logf("retained=%d sampled whole-read heap growth=%d retained-heap=%d response=%d fixture=%s read=%s", size, peak, retained, len(body), fixtureElapsed, time.Since(readStart))
						if peak > readerHeapCeiling {
							t.Errorf("Markdown read materialized retained %s: %d bytes exceeds 4 MiB", kind, peak)
						}
					}
					if err != nil {
						t.Fatal(err)
					}
					// Delivery and its assertions are outside the whole-entry heap sample.
					text, refs, warnings := continueMarkdownRead(t, f.in, body)
					if len(refs) != len(wantRefs)+optionCount {
						t.Fatalf("captured %d references, want %d", len(refs), len(wantRefs)+optionCount)
					}
					for id, want := range wantRefs {
						if got := refs[id]; got.Ref != want || got.Ver == 0 {
							t.Fatalf("missing mutation-ready reference %s: %+v, want %+v", id, got, want)
						}
					}
					// Generate the large oracle after sampling: a live map of expected refs
					// otherwise increases the GC allowance for transient reader allocations.
					for n := 0; n < optionCount; n++ {
						id := spillID(OptionKind, uint64(n+100))
						if _, exists := wantRefs[id]; exists {
							t.Fatalf("generated option overlaps fixture reference: %s", id)
						}
						want := AssignedRef{Ref: Ref{ID: id, Inc: 7}, Ver: 7}
						if got := refs[id]; got != want {
							t.Fatalf("missing mutation-ready reference %s: %+v, want %+v", id, got, want)
						}
					}
					if payload {
						fragments = append(fragments, "payloadstart"+strings.Repeat("x", size)+"payloadend")
					}
					fragments = append(fragments, "| Name | Tags", "Second", "<!-- flats:block "+string(created.Refs["owner"].Ref.ID)+" -->")
					for _, fragment := range fragments {
						if !strings.Contains(text, fragment) {
							t.Fatalf("captured Markdown missing expected %d-byte fragment (output=%d bytes)", len(fragment), len(text))
						}
					}
					if len(warnings) != 1 || warnings[0].Code != "database_display_text" {
						t.Fatalf("database fallback warnings changed: %+v", warnings)
					}
				})
			}
			if kind == "option_schema" && !large {
				t.Run("bounded_growth", func(t *testing.T) {
					for _, size := range []int{1 << 20, 16 << 20} {
						if _, ok := schemaPeaks[size]; !ok {
							t.Fatalf("option-schema live-heap sample unavailable for %d MiB; run both live cases with this comparison", size>>20)
						}
					}
					small, large := schemaPeaks[1<<20], schemaPeaks[16<<20]
					delta := int64(large) - int64(small)
					t.Logf("option-schema collected live-heap growth: 1 MiB=%d 16 MiB=%d delta=%d", small, large, delta)
					if delta > collectedGrowthBudget {
						t.Errorf("Markdown read materialized retained option schema: heap growth increased by %d bytes from 1 to 16 MiB, exceeds 1 MiB", delta)
					}
				})
			}
		})
	}
}

// measureMarkdownLiveReads keeps response slices within this frame so the
// caller's final heap sample excludes them. The file preserves the response
// from the smallest sampled peak for the continuation assertions.
func measureMarkdownLiveReads(t *testing.T, in *Instance, query []byte, responsePath string) (peak, firstBaseline uint64) {
	t.Helper()
	for attempt := 0; attempt < collectedAttempts; attempt++ {
		body, sample, baseline, err := measureReaderLiveHeap(t, in, query)
		if err != nil {
			t.Fatal(err)
		}
		t.Logf("collected live-heap sample %d/%d growth=%d baseline=%d", attempt+1, collectedAttempts, sample, baseline)
		if attempt == 0 || sample < peak {
			peak = sample
			if err := os.WriteFile(responsePath, body, 0600); err != nil {
				t.Fatalf("store measured Markdown response: %v", err)
			}
		}
		if attempt == 0 {
			firstBaseline = baseline
		}
	}
	return peak, firstBaseline
}

// collectedRetentionShift reports the positive change in settled Go heap
// across the measured reads. Unrelated heap movement can affect the result.
func collectedRetentionShift(first, last uint64) uint64 {
	if last < first {
		return 0
	}
	return last - first
}

func TestCollectedRetentionShift(t *testing.T) {
	for _, test := range []struct {
		name        string
		first, last uint64
		want        uint64
		overBudget  bool
	}{
		{"steady", 3000000, 3000000, 0, false},
		{"released", 3000000, 2900000, 0, false},
		{"small drift", 3000000, 3100000, 100000, false},
		{"retained over budget", 3000000, 3000000 + 2<<20, 2 << 20, true},
	} {
		t.Run(test.name, func(t *testing.T) {
			if shift := collectedRetentionShift(test.first, test.last); shift != test.want {
				t.Fatalf("shift(%d, %d) = %d, want %d", test.first, test.last, shift, test.want)
			} else if over := shift > collectedGrowthBudget; over != test.overBudget {
				t.Fatalf("shift %d over budget = %t, want %t", shift, over, test.overBudget)
			}
		})
	}
}

func continueMarkdownRead(t *testing.T, in *Instance, body []byte) (string, map[ID]AssignedRef, []Warning) {
	t.Helper()
	var text strings.Builder
	refs := map[ID]AssignedRef{}
	var warnings []Warning
	var state State
	for pages := 0; ; pages++ {
		if pages > 10000 || len(body) > readPageBytes {
			t.Fatal("Markdown continuation exceeded progress or response bound")
		}
		var result readResult
		if err := json.Unmarshal(body, &result); err != nil {
			t.Fatal(err)
		}
		if pages == 0 && result.State != nil {
			state = *result.State
		}
		if result.Markdown == nil || result.Offset == nil || *result.Offset != int64(text.Len()) || result.State == nil || *result.State != state || !utf8.ValidString(*result.Markdown) {
			t.Fatal("Markdown continuation changed snapshot, byte offset or UTF-8 boundaries")
		}
		text.WriteString(*result.Markdown)
		warnings = append(warnings, result.Warnings...)
		for id, ref := range result.References {
			if old, exists := refs[id]; exists && old != ref {
				t.Fatalf("reference version changed across continuations: %s", id)
			}
			refs[id] = ref
		}
		if result.Complete {
			if result.Next != nil {
				t.Fatal("completed Markdown capture returned a cursor")
			}
			return text.String(), refs, warnings
		}
		if result.Next == nil {
			t.Fatal("incomplete Markdown capture has no cursor")
		}
		body, _ = liveReadQuery(t, in, map[string]any{"cursor": *result.Next}, false)
	}
}

func TestMarkdownContinuationSnapshotVersions(t *testing.T) {
	f, created := readerQueryFixture(t)
	row, property := created.Refs["big"].Ref, created.Refs["tags"].Ref
	title := created.Refs["db.title"].Ref
	first, second := created.Refs["first"].Ref, created.Refs["second"].Ref
	before := "beforerow"
	added := liveReadUpdate(t, f, "snapshot-content",
		SetCellOp{Row: Target{Ref: &row}, Cell: CellInput{Property: Target{Ref: &property}, Value: CellInputValue{Options: []Target{{Ref: &second}, {Ref: &first}}}}},
		SetCellOp{Row: Target{Ref: &row}, Cell: CellInput{Property: Target{Ref: &title}, Value: CellInputValue{Text: &before}}},
		CreateBlockOp{CreateFields: CreateFields{Ref: "code"}, Place: Placement{Page: Target{Ref: &f.page}}, Content: Content{Kind: Code, Code: "beforecode", Language: "go"}},
		CreateBlockOp{CreateFields: CreateFields{Ref: "rich"}, Place: Placement{Page: Target{Ref: &f.page}}, Content: Content{Kind: Paragraph, Text: RichText{{Text: "beforerich", Marks: []Mark{Bold}}}}},
	)
	if err := f.in.db.transaction(t.Context(), func(tx *sql.Tx) error {
		_, err := tx.ExecContext(t.Context(), `UPDATE items SET data=json_set(data,'$.content.text',?) WHERE id=?`, strings.Repeat("beforecode\n", readPartBytes/5), added.Refs["code"].Ref.ID)
		return err
	}); err != nil {
		t.Fatal(err)
	}
	want := map[ID]AssignedRef{}
	if err := f.in.ReadTx(t.Context(), func(tx *sql.Tx, _ Sequence) error {
		ids := []ID{f.page.ID}
		for _, result := range []WriteResult{created, added} {
			for _, assigned := range result.Refs {
				ids = append(ids, assigned.Ref.ID)
			}
		}
		for _, id := range ids {
			record, err := loadRecord(t.Context(), tx, id)
			if err != nil {
				return err
			}
			want[id] = AssignedRef{Ref: record.Item.Ref, Ver: record.Item.Ver}
		}
		return nil
	}); err != nil {
		t.Fatal(err)
	}
	body, captured := liveReadQuery(t, f.in, map[string]any{"page": f.page.ID, "format": "markdown", "limit": 1}, false)
	if captured.Complete || captured.Next == nil {
		t.Fatal("fixture did not require Markdown continuations")
	}
	code, rich := added.Refs["code"].Ref, added.Refs["rich"].Ref
	after := "afterrow"
	liveReadUpdate(t, f, "after-capture",
		SetBlockOp{Block: Target{Ref: &code}, Content: Content{Kind: Code, Code: "aftercode"}},
		SetBlockOp{Block: Target{Ref: &rich}, Content: Content{Kind: Paragraph, Text: RichText{{Text: "afterrich", Marks: []Mark{}}}}},
		SetCellOp{Row: Target{Ref: &row}, Cell: CellInput{Property: Target{Ref: &title}, Value: CellInputValue{Text: &after}}},
	)
	cursor := *captured.Next
	replay, _ := liveReadQuery(t, f.in, map[string]any{"cursor": cursor}, false)
	again, _ := liveReadQuery(t, f.in, map[string]any{"cursor": cursor}, false)
	if !bytes.Equal(replay, again) {
		t.Fatal("Markdown continuation replay changed")
	}
	text, refs, warnings := continueMarkdownRead(t, f.in, body)
	if !reflect.DeepEqual(refs, want) {
		t.Fatalf("captured reference versions changed after edits: got=%+v want=%+v", refs, want)
	}
	for _, fragment := range []string{"beforecode", "**beforerich**", "| beforerow | First, Second |"} {
		if !strings.Contains(text, fragment) {
			t.Fatalf("captured Markdown missing %q", fragment)
		}
	}
	if strings.Contains(text, "aftercode") || strings.Contains(text, "afterrich") || strings.Contains(text, "afterrow") || len(warnings) != 1 || warnings[0].Code != "database_display_text" {
		t.Fatalf("capture changed after edits: warnings=%+v", warnings)
	}
}

package notebook

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"runtime"
	"runtime/debug"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

// readerHeapCeiling bounds the sampled heap growth of one whole read.
const readerHeapCeiling = 4 << 20

// measureReaderHeap reports the transient sampled heap growth of one whole
// read and, after a final collection, the heap the read still retains. The
// transient peak serves the ceiling check. Growth comparisons use a separate
// measureReaderLiveHeap read, because these transient samples mix collected
// and uncollected regimes and the final retained figure misses capture buffers.
func measureReaderHeap(t *testing.T, in *Instance, query []byte) ([]byte, uint64, uint64, error) {
	t.Helper()
	oldGC := debug.SetGCPercent(20)
	defer debug.SetGCPercent(oldGC)
	runtime.GC()
	var before runtime.MemStats
	runtime.ReadMemStats(&before)
	var peak atomic.Uint64
	peak.Store(before.HeapAlloc)
	sample := func() {
		var stats runtime.MemStats
		runtime.ReadMemStats(&stats)
		if stats.HeapAlloc > before.HeapAlloc+readerHeapCeiling {
			// Under host CPU contention the GC CPU limiter can turn off mutator
			// assists, and the heap then outgrows the pacer's goal with garbage.
			// A collection frees that garbage; what the read still holds survives.
			runtime.GC()
			runtime.ReadMemStats(&stats)
		}
		for old := peak.Load(); stats.HeapAlloc > old; old = peak.Load() {
			if peak.CompareAndSwap(old, stats.HeapAlloc) {
				break
			}
		}
	}
	in.spills.wrapWriter = func(out io.Writer) io.Writer {
		return readerWriteFunc(func(p []byte) (int, error) { sample(); return out.Write(p) })
	}
	defer func() { in.spills.wrapWriter = nil }()
	stop, joined := make(chan struct{}), make(chan struct{})
	go func() {
		defer close(joined)
		ticker := time.NewTicker(2 * time.Millisecond)
		defer ticker.Stop()
		for {
			select {
			case <-stop:
				return
			case <-ticker.C:
				sample()
			}
		}
	}()
	body, err := in.Read(t.Context(), query, false)
	sample()
	close(stop)
	<-joined
	// Collect once more for the post-return retention diagnostic, excluding
	// garbage the read no longer holds.
	runtime.GC()
	var after runtime.MemStats
	runtime.ReadMemStats(&after)
	var retained uint64
	if after.HeapAlloc > before.HeapAlloc {
		retained = after.HeapAlloc - before.HeapAlloc
	}
	return body, peak.Load() - before.HeapAlloc, retained, err
}

// measureReaderLiveHeap samples collected live heap throughout a fresh read.
// The ticker covers preparation before output; writes add bounded checkpoints.
// It also reports the post-collection baseline the growth is measured from,
// so callers can tell retained heap (baseline shift across reads) apart from
// transient in-read peaks.
func measureReaderLiveHeap(t *testing.T, in *Instance, query []byte) ([]byte, uint64, uint64, error) {
	t.Helper()
	oldGC := debug.SetGCPercent(20)
	defer debug.SetGCPercent(oldGC)
	before := settledReaderHeap()
	t.Logf("collected live-heap baseline=%d", before)
	peak := before
	var mu sync.Mutex
	sample := func() {
		mu.Lock()
		defer mu.Unlock()
		runtime.GC()
		var stats runtime.MemStats
		runtime.ReadMemStats(&stats)
		peak = max(peak, stats.HeapAlloc)
	}
	var written atomic.Uint64
	in.spills.wrapWriter = func(out io.Writer) io.Writer {
		return readerWriteFunc(func(p []byte) (int, error) {
			after := written.Add(uint64(len(p)))
			before := after - uint64(len(p))
			if before == 0 || before/(64<<10) != after/(64<<10) {
				sample()
			}
			return out.Write(p)
		})
	}
	defer func() { in.spills.wrapWriter = nil }()
	stop, joined := make(chan struct{}), make(chan struct{})
	var periodic int
	go func() {
		defer close(joined)
		ticker := time.NewTicker(2 * time.Millisecond)
		defer ticker.Stop()
		for {
			select {
			case <-stop:
				return
			case <-ticker.C:
				sample()
				periodic++
			}
		}
	}()
	body, err := in.Read(t.Context(), query, false)
	sample()
	close(stop)
	<-joined
	t.Logf("collected live-heap periodic samples=%d", periodic)
	return body, peak - before, before, err
}

// settledReaderHeap uses a second collection to release pool victims.
func settledReaderHeap() uint64 {
	runtime.GC()
	runtime.GC()
	var stats runtime.MemStats
	runtime.ReadMemStats(&stats)
	return stats.HeapAlloc
}

func readerQueryFixture(t *testing.T) (writerFixture, WriteResult) {
	t.Helper()
	f := liveReadFixture(t)
	created := liveReadUpdate(t, f, "schema",
		CreateDatabaseOp{CreateFields: CreateFields{Ref: "db"}, BlockRef: "owner", Place: Placement{Page: Target{Ref: &f.page}}, Title: "Tasks"},
		CreatePropertyOp{CreateFields: CreateFields{Ref: "tags"}, Database: Target{Tmp: "db"}, Definition: PropertyDef{Name: "Tags", Type: MultiSelectType}},
		CreateOptionOp{CreateFields: CreateFields{Ref: "first"}, Property: Target{Tmp: "tags"}, Name: "First", Color: "gray"},
		CreateOptionOp{CreateFields: CreateFields{Ref: "second"}, Property: Target{Tmp: "tags"}, Name: "Second", Color: "gray"},
		CreateRowOp{CreateFields: CreateFields{Ref: "big"}, Database: Target{Tmp: "db"}, Cells: []CellInput{}},
		CreateRowOp{CreateFields: CreateFields{Ref: "small"}, Database: Target{Tmp: "db"}, Cells: []CellInput{{Property: Target{Tmp: "tags"}, Value: CellInputValue{Options: []Target{{Tmp: "second"}}}}}},
	)
	return f, created
}

func readerMemorySizes() []int {
	sizes := []int{1 << 20, 3 << 19}
	if os.Getenv("NOTEBOOK_LARGE_MEMORY_TESTS") == "1" {
		sizes = append(sizes, 8<<20, 32<<20)
	}
	return sizes
}

func TestReaderSelectionPreparationMemory(t *testing.T) {
	for _, kind := range []string{"database", "owner", "property", "view"} {
		t.Run(kind, func(t *testing.T) {
			for _, size := range readerMemorySizes() {
				t.Run(fmt.Sprintf("%gMiB", float64(size)/(1<<20)), func(t *testing.T) {
					f, created := readerQueryFixture(t)
					database := created.Refs["db"].Ref
					query := map[string]any{"database": database.ID, "limit": 1}
					id, path := database.ID, "$.title"
					switch kind {
					case "owner":
						child := liveReadUpdate(t, f, "child", CreatePageOp{CreateFields: CreateFields{Ref: "child"}, Parent: &Target{Ref: &f.page}, Title: "Child"})
						id, path = f.page.ID, "$.title"
						query = map[string]any{"page": child.Refs["child"].Ref.ID, "limit": 1}
					case "property":
						property := created.Refs["db.title"].Ref
						id, path = property.ID, "$.definition.name"
						query["sort"] = []Sort{{Property: Target{Ref: &property}, Direction: "asc"}}
					case "view":
						id, path = created.Refs["db.view"].Ref.ID, "$.definition.name"
						query["view"] = id
					}
					if err := f.in.db.transaction(t.Context(), func(tx *sql.Tx) error {
						_, err := tx.ExecContext(t.Context(), `UPDATE items SET data=json_set(data,?,?) WHERE id=?`, path, strings.Repeat("x", size), id)
						return err
					}); err != nil {
						t.Fatal(err)
					}
					raw, _ := json.Marshal(query)
					body, peak, _, err := measureReaderHeap(t, f.in, raw)
					if err != nil {
						t.Fatal(err)
					}
					var result readResult
					if err := json.Unmarshal(body, &result); err != nil {
						t.Fatal(err)
					}
					if kind == "owner" {
						if result.Page == nil || !result.Complete || len(result.Page.Items) != 1 {
							t.Fatalf("missing captured page: %s", body)
						}
						var item struct {
							Parent Ref `json:"parent_ref"`
						}
						if err := json.Unmarshal(result.Page.Items[0], &item); err != nil || item.Parent != f.page {
							t.Fatalf("missing owner reference: %s", body)
						}
					} else if result.Schema == nil || result.Complete || result.Next == nil {
						t.Fatalf("missing captured schema/cursor: %s", body)
					}
					// Bound above the heap immediately before Instance.Read, including
					// preparation, query, capture, reference indexing and delivery.
					t.Logf("whole read sampled heap growth: %d bytes", peak)
					if peak > readerHeapCeiling {
						t.Fatalf("read preparation materialized retained payload: %d bytes", peak)
					}
				})
			}
		})
	}
}

func TestReaderCollectionOrderingParity(t *testing.T) {
	for _, tc := range []struct {
		name                          string
		reverse, descending, filtered bool
		wantBigFirst                  bool
	}{
		{name: "schema_order", wantBigFirst: true},
		{name: "reversed_cell_order", reverse: true, wantBigFirst: true},
		{name: "descending", descending: true},
		{name: "contains", reverse: true, filtered: true, wantBigFirst: true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			f, created := readerQueryFixture(t)
			property := created.Refs["tags"].Ref
			ids := []ID{created.Refs["first"].Ref.ID, created.Refs["second"].Ref.ID}
			if tc.reverse {
				ids[0], ids[1] = ids[1], ids[0]
			}
			cell, err := EncodeCellValue(CellValue{Type: MultiSelectType, Value: ids})
			if err != nil {
				t.Fatal(err)
			}
			if err := f.in.db.transaction(t.Context(), func(tx *sql.Tx) error {
				_, err := tx.ExecContext(t.Context(), `INSERT INTO cells(row_id,property_id,value) VALUES(?,?,?)`, created.Refs["big"].Ref.ID, property.ID, string(cell))
				return err
			}); err != nil {
				t.Fatal(err)
			}
			direction := "asc"
			if tc.descending {
				direction = "desc"
			}
			query := map[string]any{"database": created.Refs["db"].Ref.ID, "sort": []Sort{{Property: Target{Ref: &property}, Direction: direction}}}
			if tc.filtered {
				option := created.Refs["first"].Ref
				operand, _ := json.Marshal(option)
				query["filter"] = []Filter{{Property: Target{Ref: &property}, Op: Contains, Value: operand}}
			}
			_, result := liveReadQuery(t, f.in, query, false)
			wantCount := 2
			if tc.filtered {
				wantCount = 1
			}
			if !result.Complete || result.Rows == nil || len(*result.Rows) != wantCount {
				t.Fatalf("incomplete collection query: %+v", result)
			}
			var first struct {
				Ref Ref `json:"ref"`
			}
			if err := json.Unmarshal((*result.Rows)[0], &first); err != nil {
				t.Fatal(err)
			}
			want := created.Refs["small"].Ref
			if tc.wantBigFirst {
				want = created.Refs["big"].Ref
			}
			if first.Ref != want {
				t.Fatalf("first row=%v, want %v", first.Ref, want)
			}
		})
	}
}

func TestReaderCollectionQueryMemory(t *testing.T) {
	for _, filtered := range []bool{false, true} {
		t.Run(fmt.Sprintf("contains=%t", filtered), func(t *testing.T) {
			for _, size := range readerMemorySizes() {
				t.Run(fmt.Sprintf("%gMiB", float64(size)/(1<<20)), func(t *testing.T) {
					f, created := readerQueryFixture(t)
					property := created.Refs["tags"].Ref
					row := created.Refs["big"].Ref
					var stored strings.Builder
					stored.WriteString(`{"type":"multi_select","value":[`)
					for n := uint64(100); stored.Len() < size; n++ {
						if n > 100 {
							stored.WriteByte(',')
						}
						id := spillID(OptionKind, n)
						if err := id.ValidateKind(OptionKind); err != nil {
							t.Fatal(err)
						}
						fmt.Fprintf(&stored, "%q", id)
					}
					fmt.Fprintf(&stored, ",%q]}", created.Refs["first"].Ref.ID)
					if err := f.in.db.transaction(t.Context(), func(tx *sql.Tx) error {
						_, err := tx.ExecContext(t.Context(), `INSERT INTO cells(row_id,property_id,value) VALUES(?,?,?)`, row.ID, property.ID, stored.String())
						return err
					}); err != nil {
						t.Fatal(err)
					}
					stored.Reset()
					query := map[string]any{"database": created.Refs["db"].Ref.ID, "limit": 1, "sort": []Sort{{Property: Target{Ref: &property}, Direction: "asc"}}}
					if filtered {
						query["filter"] = []Filter{{Property: Target{Ref: &property}, Op: Contains, Value: json.RawMessage(fmt.Sprintf(`{"id":%q,"inc":%q}`, created.Refs["first"].Ref.ID, fmt.Sprint(created.Refs["first"].Ref.Inc)))}}
					}
					raw, _ := json.Marshal(query)
					body, peak, _, err := measureReaderHeap(t, f.in, raw)
					if err != nil {
						t.Fatal(err)
					}
					var result readResult
					if err := json.Unmarshal(body, &result); err != nil {
						t.Fatal(err)
					}
					if result.Next == nil {
						t.Fatal("capture has no cursor")
					}
					position, _, _, err := decodeReadCursor(*result.Next)
					if err != nil {
						t.Fatal(err)
					}
					spill, ok := f.in.spills.Lookup(position.Token)
					if !ok {
						t.Fatal("capture disappeared")
					}
					c, closeFiles, err := agentFiles(spill)
					if err != nil {
						t.Fatal(err)
					}
					defer closeFiles()
					wantRows := int64(2)
					if filtered {
						wantRows = 1
					}
					summary, err := c.node(c.root)
					if err != nil || summary.rows != wantRows {
						t.Fatalf("captured rows = %d, want %d: %v", summary.rows, wantRows, err)
					}
					first, err := c.at(true, 0)
					if err != nil {
						t.Fatal(err)
					}
					id, err := readRecordID(io.NewSectionReader(c.s.data, first.start, first.length), false)
					if err != nil || id != row.ID {
						t.Fatalf("collection query order/membership: %s %v", id, err)
					}
					t.Logf("whole collection read sampled heap growth: %d bytes", peak)
					if peak > readerHeapCeiling {
						t.Fatalf("query materialized retained collection: %d bytes", peak)
					}
				})
			}
		})
	}
}
